`#include <stdexcept>
#include <string>

class BankAccount {
private:
    std::string accountNumber;
    double balance;

public:
    BankAccount(std::string number, double openingBalance)
        : accountNumber(std::move(number)), balance(openingBalance) {}

    void deposit(double amount) {
        if (amount <= 0) throw std::invalid_argument("amount must be positive");
        balance += amount;
    }

    double getBalance() const { return balance; }
};`

`class BankAccount:
    def __init__(self, account_number: str, opening_balance: float):
        self._account_number = account_number
        self._balance = opening_balance

    def deposit(self, amount: float) -> None:
        if amount <= 0:
            raise ValueError("amount must be positive")
        self._balance += amount

    @property
    def balance(self) -> float:
        return self._balance

account = BankAccount("A-104", 500.00)
account.deposit(100.00)
print(account.balance)  # 600.0`
